SELECT id, operator_id, action, object_type, object_id, result, trace_id, created_at
FROM operation_log WHERE 1 = 1
AND operator_id = #{operatorId}
AND action = #{action}
AND object_type = #{objectType}
AND result = #{result}
AND created_at >= #{from}
AND created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
ORDER BY created_at DESC, id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM operation_log WHERE 1 = 1
AND operator_id = #{operatorId}
AND action = #{action}
AND object_type = #{objectType}
AND result = #{result}
AND created_at >= #{from}
AND created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
